CREATE VIRTUAL TABLE t1 USING fts4(matchinfo=fts3);INSERT INTO t1(rowid,content)VALUES(1,replace(hex(zeroblob(100000)),'00','zm ')),(2,replace(hex(zeroblob(100000)),'00','jk ')),(48,'zm aayxpmve csjqxhgj xnxhf xr jk aayxpmve xnxhf zm zm'),(65,'duszemmzl zk jk jk fibokdry jseuhjnzo zm aayxpmve zk jk'),(84,'zf jmfiqhwnjg js igju zm aayxpmve zm mbxnljomiv csjqxhgj nvfasfh');WITH RECURSIVE c(x)AS(VALUES(1)UNION ALL SELECT x+1 FROM c WHERE x<1000)INSERT INTO t1(content)SELECT '' FROM c;UPDATE t1_segments SET block=zeroblob(length(block)) WHERE length(block)>10000;